import java.util.*;

class Solution {
    public List<String> findItinerary(List<List<String>> tickets) {
        Map<String, PriorityQueue<String>> graph = new HashMap<>();
        for (List<String> ticket : tickets) {
            graph.computeIfAbsent(ticket.get(0), key -> new PriorityQueue<>()).offer(ticket.get(1));
        }

        LinkedList<String> route = new LinkedList<>();
        Deque<String> stack = new ArrayDeque<>();
        stack.push("JFK");

        while (!stack.isEmpty()) {
            String airport = stack.peek();
            PriorityQueue<String> destinations = graph.get(airport);
            if (destinations != null && !destinations.isEmpty()) {
                stack.push(destinations.poll());
            } else {
                route.addFirst(stack.pop());
            }
        }
        return route;
    }
}

import java.util.*;

class Solution {
    private final Map<String, List<String>> graph = new HashMap<>();
    private final LinkedList<String> route = new LinkedList<>();

    public List<String> findItinerary(List<List<String>> tickets) {
        for (List<String> ticket : tickets) {
            graph.computeIfAbsent(ticket.get(0), key -> new ArrayList<>()).add(ticket.get(1));
        }
        for (List<String> destinations : graph.values()) {
            destinations.sort(Collections.reverseOrder());
        }
        dfs("JFK");
        return route;
    }

    private void dfs(String airport) {
        List<String> destinations = graph.get(airport);
        while (destinations != null && !destinations.isEmpty()) {
            String next = destinations.remove(destinations.size() - 1);
            dfs(next);
        }
        route.addFirst(airport);
    }
}

import java.util.*;

class Solution {
    public List<String> findItinerary(List<List<String>> tickets) {
        Map<String, TreeMap<String, Integer>> graph = new HashMap<>();
        for (List<String> ticket : tickets) {
            graph.computeIfAbsent(ticket.get(0), key -> new TreeMap<>())
                    .merge(ticket.get(1), 1, Integer::sum);
        }

        List<String> route = new ArrayList<>();
        route.add("JFK");
        backtrack("JFK", tickets.size(), graph, route);
        return route;
    }

    private boolean backtrack(String airport, int ticketCount,
                              Map<String, TreeMap<String, Integer>> graph,
                              List<String> route) {
        if (route.size() == ticketCount + 1) return true;
        TreeMap<String, Integer> destinations = graph.get(airport);
        if (destinations == null) return false;

        for (String next : new ArrayList<>(destinations.keySet())) {
            int count = destinations.get(next);
            if (count == 0) continue;
            destinations.put(next, count - 1);
            route.add(next);
            if (backtrack(next, ticketCount, graph, route)) return true;
            route.remove(route.size() - 1);
            destinations.put(next, count);
        }
        return false;
    }
}
